root=Path(__file__).resolve().parents[1]
def load(name):
    path=root/name
    if not path.exists():
        path=Path(str(path)+".gz")
    with (gzip.open(path,"rt") if path.suffix==".gz" else path.open()) as stream:
        return json.load(stream)
