def label(item):
    obj=items.get(item["uuid"],{})
    name=(obj["ref"]+"."+obj["number"]) if obj.get("kind")=="pads" else item["description"]
    return name.replace("|","/")+f" @ ({item['pos']['x']:.6f}, {item['pos']['y']:.6f})"

blocked=[]
for index,entry in enumerate(final["unconnected_items"],1):
    net=next((m.group(1) for item in entry["items"] if (m:=re.search(r"\[([^]]+)\]",item["description"]))),"unknown")
    attempts=ledger.get(net,{}).get("attempts",[])
    if net in exhausted:
        reason="Historical U7 escape attempts exhausted; no further retry permitted."
    elif net=="SPI_MOSI":
        reason="Prior U7 escape attempts exhausted; other branches halted by the global R8/R9 stop."
    elif net=="+3V3":
        reason="Remaining plane/sensor branches unresolved; U11 escape exhausted. Global stop prohibits further routing."
    elif net=="GND":
        reason="Remaining HV-stranded branches: prior legal surface-stitch approach failed; global stop."
    elif attempts:
        reason="No accepted complete path in the logged bounded approach; global stop after R8/R9."
    else:
        reason="Unfinished connection; no further attempt permitted after the global R8/R9 stop."
    blocked.append({"id":index,"net":net,"reason":reason,"endpoints":entry["items"],"endpoint_labels":[label(i) for i in entry["items"]],"logged_restart_attempts":attempts})
